  "config-errors": {
    "solutionCode": "use std::collections::HashMap;\nuse std::fmt;\nuse std::num::ParseIntError;\n\n#[derive(Debug, PartialEq)]\npub enum ConfigError {\n    MissingKey(String),\n    InvalidFormat(String),\n    ParseError(String),\n    ValidationError(String),\n}\n\nimpl fmt::Display for ConfigError {\n    fn fmt(&self, f: &mut fmt::Formatter) -> fmt::Result {\n        match self {\n            ConfigError::MissingKey(k) => write!(f, \"missing key: {k}\"),\n            ConfigError::InvalidFormat(m) => write!(f, \"invalid format: {m}\"),\n            ConfigError::ParseError(m) => write!(f, \"parse error: {m}\"),\n            ConfigError::ValidationError(m) => write!(f, \"{m}\"),\n        }\n    }\n}\n\nimpl From<ParseIntError> for ConfigError {\n    fn from(err: ParseIntError) -> Self {\n        ConfigError::ParseError(err.to_string())\n    }\n}\n\n#[derive(Debug, PartialEq)]\npub struct Config {\n    pub port: u16,\n    pub host: String,\n    pub max_connections: usize,\n}\n\nimpl Config {\n    pub fn new(port: u16, host: String, max_connections: usize) -> Result<Self, ConfigError> {\n        Self::validate_port(port)?;\n        Self::validate_host(&host)?;\n        Self::validate_max_connections(max_connections)?;\n        Ok(Self {\n            port,\n            host,\n            max_connections,\n        })\n    }\n\n    fn validate_port(port: u16) -> Result<(), ConfigError> {\n        if port == 0 {\n            return Err(ConfigError::ValidationError(\n                \"port must be between 1 and 65535\".into(),\n            ));\n        }\n        Ok(())\n    }\n\n    fn validate_host(host: &str) -> Result<(), ConfigError> {\n        if host.is_empty() {\n            return Err(ConfigError::ValidationError(\n                \"host must not be empty\".into(),\n            ));\n        }\n        Ok(())\n    }\n\n    fn validate_max_connections(max_connections: usize) -> Result<(), ConfigError> {\n        if max_connections == 0 || max_connections > 10000 {\n            return Err(ConfigError::ValidationError(\n                \"max_connections must be between 1 and 10000\".into(),\n            ));\n        }\n        Ok(())\n    }\n}\n\npub fn parse_config(input: &str) -> Result<Config, ConfigError> {\n    let mut map = HashMap::new();\n    for (idx, raw) in input.lines().enumerate() {\n        let line = raw.trim();\n        if line.is_empty() {\n            continue;\n        }\n        let Some((k, v)) = line.split_once('=') else {\n            return Err(ConfigError::InvalidFormat(format!(\n                \"line {}: {line}\",\n                idx + 1\n            )));\n        };\n        map.insert(k.trim().to_string(), v.trim().to_string());\n    }\n\n    let port_s = map\n        .get(\"port\")\n        .ok_or_else(|| ConfigError::MissingKey(\"port\".into()))?;\n    let host = map\n        .get(\"host\")\n        .ok_or_else(|| ConfigError::MissingKey(\"host\".into()))?\n        .clone();\n    let max_s = map\n        .get(\"max_connections\")\n        .ok_or_else(|| ConfigError::MissingKey(\"max_connections\".into()))?;\n\n    let port: u16 = port_s.parse().map_err(|e: ParseIntError| ConfigError::from(e))?;\n    let max_connections: usize = max_s\n        .parse()\n        .map_err(|e: ParseIntError| ConfigError::from(e))?;\n\n    Config::new(port, host, max_connections)\n}\n",
    "solutionWalkthrough": "Parse key=value lines into a map, require port/host/max_connections, convert parse failures into ConfigError, then validate ranges (port 1..=65535, non-empty host, connections 1..=10000)."
  },
