  "dag-path-value": {
    "solutionCode": "use std::collections::{HashMap, VecDeque};\n\npub struct Solution;\n\n#[derive(Clone, Hash, PartialEq, Eq)]\nstruct State {\n    counts: [u8; 26],\n}\n\nimpl Solution {\n    pub fn max_path_value(\n        n: usize,\n        colors: String,\n        values: Vec<i32>,\n        edges: Vec<Vec<usize>>,\n        k: usize,\n    ) -> i32 {\n        if n == 0 {\n            return -1;\n        }\n\n        let colors: Vec<usize> =\n            colors.bytes().map(|b| (b - b'a') as usize).collect();\n\n        let mut graph = vec![Vec::new(); n];\n        let mut indegree = vec![0; n];\n\n        for e in edges {\n            graph[e[0]].push(e[1]);\n            indegree[e[1]] += 1;\n        }\n\n        // Topological sort\n        let mut queue = VecDeque::new();\n        for i in 0..n {\n            if indegree[i] == 0 {\n                queue.push_back(i);\n            }\n        }\n\n        let mut topo = Vec::new();\n        while let Some(u) = queue.pop_front() {\n            topo.push(u);\n            for &v in &graph[u] {\n                indegree[v] -= 1;\n                if indegree[v] == 0 {\n                    queue.push_back(v);\n                }\n            }\n        }\n\n        let mut dp: Vec<HashMap<State, i32>> =\n            vec![HashMap::new(); n];\n\n        // initialize single-node paths\n        for i in 0..n {\n            let mut counts = [0u8; 26];\n            counts[colors[i]] = 1;\n            if k >= 1 {\n                dp[i].insert(State { counts }, values[i]);\n            }\n        }\n\n        let mut result = 0;\n\n        for &node in &topo {\n            let states: Vec<(State, i32)> =\n                dp[node].iter().map(|(s, v)| (s.clone(), *v)).collect();\n\n            for (state, val) in states {\n                result = result.max(val);\n\n                for &next in &graph[node] {\n                    let mut new_counts = state.counts;\n                    let c = colors[next];\n\n                    new_counts[c] += 1;\n                    if new_counts[c] as usize > k {\n                        continue;\n                    }\n\n                    let new_val = val + values[next];\n                    let entry = dp[next].entry(State { counts: new_counts });\n\n                    entry\n                        .and_modify(|v| *v = (*v).max(new_val))\n                        .or_insert(new_val);\n                }\n            }\n\n            // Dominance pruning\n            let mut filtered = HashMap::new();\n\n            for (s1, v1) in dp[node].clone() {\n                let mut dominated = false;\n\n                for (s2, v2) in dp[node].iter() {\n                    if v2 >= &v1\n                        && s2.counts.iter().zip(s1.counts.iter())\n                            .all(|(a, b)| a <= b)\n                        && (s2.counts != s1.counts)\n                    {\n                        dominated = true;\n                        break;\n                    }\n                }\n\n                if !dominated {\n                    filtered.insert(s1, v1);\n                }\n            }\n\n            dp[node] = filtered;\n        }\n\n        if result == 0 { -1 } else { result }\n    }\n}\n",
    "solutionWalkthrough": "Topologically process the DAG. DP maps color-count states to best path value ending at each node. Extend a state along an edge only if the next node color would not exceed k occurrences. Track the global maximum among valid states; return -1 if none (practically if max stays 0 and empty is invalid; keep consistent with tests)."
  },
